"""
Seed all 385 catalog items from AFL Item Master Catalog v5.
Run via: python seed/catalog_seed.py  OR called from main.py on startup.
"""
from sqlalchemy.orm import Session
from models.catalog import CatalogItem

def _item(**kw) -> dict:
    defaults = dict(
        status="active", custom_quote_flag=False,
        contains_lithium_battery=False, fragility_level="Medium",
    )
    defaults.update(kw)
    return defaults

# ── helper shorthand ─────────────────────────────────────────────────────────
def _phone(pid, name, brand, weight, priority, tier, aliases, battery=True):
    return _item(
        product_id=pid, item_name=name, brand=brand,
        category="Phones & Tablets", product_category="Smartphone",
        avg_weight_kg=weight, dim_l_inches=6, dim_w_inches=3, dim_h_inches=1,
        shipping_mode="air", contains_lithium_battery=battery,
        fragility_level="High" if priority >= 78 else "Medium",
        search_keywords="smartphone, mobile phone, cellphone, mobile, handset",
        detection_priority=priority, detection_tier_hint=tier,
        default_engine_hint="FLAT",
        image_url=f"products/{brand.lower()}/{name.lower().replace(' ','_').replace('/','_')}.png",
        aliases=aliases,
    )

def _tablet(pid, name, brand, weight, l, w, h, priority, tier, aliases):
    return _item(
        product_id=pid, item_name=name, brand=brand,
        category="Phones & Tablets", product_category="Tablet",
        avg_weight_kg=weight, dim_l_inches=l, dim_w_inches=w, dim_h_inches=h,
        shipping_mode="air", contains_lithium_battery=True, fragility_level="High",
        search_keywords="tablet, ipad, android tablet, touch screen tablet",
        detection_priority=priority, detection_tier_hint=tier,
        default_engine_hint="FLAT",
        image_url=f"products/{brand.lower()}/{name.lower().replace(' ','_').replace('/','_')}.png",
        aliases=aliases,
    )

def _laptop(pid, name, brand, weight, pcat, priority, tier, aliases, battery=True):
    fragility = "High" if "MacBook" in name or priority >= 90 else "Medium"
    return _item(
        product_id=pid, item_name=name, brand=brand,
        category="Laptops & Desktops", product_category=pcat,
        avg_weight_kg=weight, dim_l_inches=15, dim_w_inches=10, dim_h_inches=2,
        shipping_mode="air", contains_lithium_battery=battery, fragility_level=fragility,
        search_keywords="laptop, notebook, portable computer, slim laptop",
        detection_priority=priority, detection_tier_hint=tier,
        default_engine_hint="VALUE_BAND",
        image_url=f"products/{brand.lower()}/{name.lower().replace(' ','_').replace('/','_')}.png",
        aliases=aliases,
    )

def _gpu(pid, name, brand, weight, l, w, h, priority, tier):
    return _item(
        product_id=pid, item_name=name, brand=brand,
        category="PC Parts", product_category="GPU",
        avg_weight_kg=weight, dim_l_inches=l, dim_w_inches=w, dim_h_inches=h,
        shipping_mode="air", contains_lithium_battery=False, fragility_level="Medium",
        search_keywords="gpu, graphics card, video card, graphics processing unit, gaming gpu",
        detection_priority=priority, detection_tier_hint=tier, default_engine_hint="HYBRID",
        image_url=f"products/{brand.lower()}/{name.lower().replace(' ','_').replace('/','_')}.png",
        aliases=name.replace("NVIDIA ","").replace("AMD ",""),
    )

def _cpu(pid, name, brand, aliases):
    return _item(
        product_id=pid, item_name=name, brand=brand,
        category="PC Parts", product_category="CPU",
        avg_weight_kg=0.4 if "Intel" in brand else 0.35,
        dim_l_inches=6, dim_w_inches=5, dim_h_inches=2,
        shipping_mode="air", contains_lithium_battery=False, fragility_level="Medium",
        search_keywords="cpu, processor, chip, central processing unit",
        detection_priority=80, detection_tier_hint="HIGH_VALUE", default_engine_hint="HYBRID",
        image_url=f"products/{brand.lower()}/{name.lower().replace(' ','_').replace('/','_')}.png",
        aliases=aliases,
    )

