def seed_catalog(db: Session) -> None:
    existing = {r.product_id for r in db.query(CatalogItem.product_id).all()}
    new_items = [i for i in CATALOG if i["product_id"] not in existing]
    if not new_items:
        print("[seed] Catalog already seeded — skipping.")
        return
    for data in new_items:
        db.add(CatalogItem(**data))
    db.commit()
    print(f"[seed] Catalog seeded: {len(new_items)} new items added ({len(CATALOG)} total defined).")
